import java.util.*;

import lombok.*;

public class Main {
    public static void main(String[] args) {
        Uang a = new Uang(50000, "IDR");
        Uang b = a.tambah(new Uang(25000, "IDR"));
        System.out.println(a);
        System.out.println(b);
        System.out.println(b.equals(new Uang(75000, "IDR")));
    }
}

@Value
class Uang {
    long jumlah;
    String mataUang;

    Uang tambah(Uang lain) {
        return new Uang(jumlah + lain.jumlah, mataUang);
    }
}

