public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        List<Nilai> semua = new ArrayList<>();
        while (in.hasNextLine()) {
            String[] d = in.nextLine().split(";");
            semua.add(new Nilai(d[0], Integer.parseInt(d[1])));
        }
        Nilai tertinggi = semua.get(0);
        for (Nilai n : semua) {
            if (n.getSkor() > tertinggi.getSkor()) {
                tertinggi = n;
            }
        }
        System.out.println("Tertinggi: " + tertinggi);
        System.out.println("Ada Budi 80? " + semua.contains(new Nilai("Budi", 80)));
    }
}

class Nilai {
    String nama;
    int skor;
}

